<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { ArrowRight, Check, Eye, LayoutTemplate, X } from '@lucide/vue';
import CanvasPreview from './CanvasPreview.vue';
import { preserveHeroCopy } from '../../lib/design-copy';
import { categories, categoryFor, makeModules, modulePurpose, sampleProject, sourceAsset, templates, updateProjectTemplate, type ProductCategory, type Project, type TemplateId } from '../../lib/design-model';

const props = defineProps<{ currentProject: Project | null; busy: boolean }>();
const emit = defineEmits<{ use: [template: TemplateId, category: ProductCategory, output: 'main' | 'detail'] }>();
const category = ref<ProductCategory>(props.currentProject ? categoryFor(props.currentProject).id : 'quilt');
const output = ref<'main' | 'detail'>(props.currentProject?.output || 'main');
const previewId = ref<TemplateId | null>(null);
const dialog = ref<HTMLDialogElement | null>(null);
const example = sampleProject();
const hasOriginals = computed(() => !!props.currentProject?.assets.some(asset => !asset.generated));
const appliesToCurrent = computed(() => !!props.currentProject && categoryFor(props.currentProject).id === category.value && (props.currentProject.output || 'main') === output.value);
const source = computed(() => hasOriginals.value ? props.currentProject! : example);
const categoryName = computed(() => categories.find(item => item.id === category.value)!.name);
const outputName = computed(() => output.value === 'main' ? '商品主图' : '商品详情');
const count = computed(() => output.value === 'main' ? 5 : 7);
const useLabel = computed(() => appliesToCurrent.value ? '应用到当前作品' : '用此模板新建');
const notice = computed(() => !hasOriginals.value ? category.value === 'bedding-set' ? '用内置被子实拍演示套件排版，制作时请换成实际套件图片。' : '以下用内置商品样例展示真实排版。' : appliesToCurrent.value ? `用「${source.value.info.name || '当前商品'}」的实拍与文案预览。` : `用当前实拍演示${outputName.value}排版，使用后会新建空白商品。`);
const applyNotice = computed(() => appliesToCurrent.value ? '保留商品资料、首图文案；用途相同的图片保留文案、选图与裁切。' : '新建空白商品，随后上传对应实拍。当前作品的修改会先提醒保存。');
function previewProject(template: TemplateId): Project {
  const original = source.value;
  const preserve = hasOriginals.value && appliesToCurrent.value;
  const arranged = preserve ? updateProjectTemplate(original, template) : original;
  const p: Project = { ...arranged, template, category: category.value, output: output.value, assets: original.assets.filter(asset => !asset.generated), modules: [], generation: 'template', generationBatch: undefined, workflow: 'plan' };
  p.modules = preserve && arranged.modules.some(module => module.kind === output.value)
    ? arranged.modules.filter(module => module.kind === output.value).map(module => ({ ...module, imageId: sourceAsset(arranged, module)?.id || module.sourceImageId || module.imageId, imageId2: module.sourceImageId2 ?? module.imageId2, aiStatus: undefined, aiError: undefined }))
    : preserveHeroCopy(original, makeModules(p));
  return p;
}
const designs = computed(() => templates.map(template => ({ template, project: previewProject(template.id) })));
const preview = computed(() => designs.value.find(item => item.template.id === previewId.value));
watch(previewId, async id => {
  await nextTick();
  if (id && dialog.value && !dialog.value.open) dialog.value.showModal();
  else if (!id && dialog.value?.open) dialog.value.close();
});
function useTemplate(template: TemplateId) {
  if (props.busy) return;
  emit('use', template, category.value, output.value);
  previewId.value = null;
}
function isCurrent(template: TemplateId) {
  return appliesToCurrent.value && props.currentProject?.template === template;
}
</script>

<template>
  <div class="template-library">
    <header class="page-heading"><div><span class="eyebrow">MADE FOR YOUR PRODUCT</span><h1>先看风格，再做选择。</h1><p>四种完整排版，让照片、文案与商品的气质对上。</p></div><span class="total-tag"><LayoutTemplate :size="14" /> {{ templates.length }} 款模板</span></header>
    <section class="filter-bar" aria-label="筛选模板"><div class="filter-group"><span>商品类目</span><div class="filter-options"><button v-for="item in categories" :key="item.id" :aria-pressed="category === item.id" @click="category = item.id">{{ item.name }}</button></div></div><span class="filter-divider" /><div class="filter-group"><span>图片用途</span><div class="filter-options"><button :aria-pressed="output === 'main'" @click="output = 'main'">商品主图 <small>5 张</small></button><button :aria-pressed="output === 'detail'" @click="output = 'detail'">商品详情 <small>7 张</small></button></div></div></section>
    <div class="results-heading"><p>{{ categoryName }} <span>/</span> {{ outputName }} <span>·</span> {{ templates.length }} 款风格</p><span>{{ notice }}</span></div>
    <div class="template-grid"><article v-for="design in designs" :key="design.template.id" class="template-card" :class="{ current: isCurrent(design.template.id) }"><button class="art-button" :aria-label="`预览${design.template.name}模板`" @click="previewId = design.template.id"><div class="canvas-wrap" :class="{ detail: output === 'detail' }"><CanvasPreview :project="design.project" :module="design.project.modules[0]" /></div><span class="art-label">{{ outputName }} · {{ count }} 张</span><span class="preview-hover"><Eye :size="16" /> 查看完整排版</span></button><div class="card-content"><div class="card-heading"><h2>{{ design.template.name }}</h2><span v-if="isCurrent(design.template.id)" class="current-label"><Check :size="11" /> 当前风格</span></div><p>{{ design.template.description }}</p><div class="style-tags"><span v-for="tag in design.template.tag.split(' · ')" :key="tag">{{ tag }}</span></div><div class="card-actions"><button class="preview-button" @click="previewId = design.template.id"><Eye :size="14" /> 预览</button><button class="use-button" :disabled="busy" @click="useTemplate(design.template.id)">{{ useLabel }} <ArrowRight :size="14" /></button></div></div></article></div>
    <div class="apply-note"><span class="note-icon"><Check :size="16" /></span><div><strong>{{ appliesToCurrent ? '应用到当前作品' : '新建商品作品' }}</strong><p>{{ applyNotice }} 模板预览使用实拍排版，可继续修改图片与文案。</p></div></div>

    <dialog ref="dialog" class="preview-dialog" aria-labelledby="template-preview-title" @cancel.prevent="previewId = null" @close="previewId = null" @click="event => { if (event.target === dialog) previewId = null; }"><template v-if="preview"><header class="preview-heading"><div><span class="eyebrow">{{ categoryName }} / {{ outputName }}</span><h2 id="template-preview-title">{{ preview.template.name }}</h2><p>{{ notice }} 以下预览前 3 张，整套共 {{ count }} 张。</p></div><button class="close-button" aria-label="关闭模板预览" @click="previewId = null"><X :size="21" /></button></header><div class="preview-gallery"><figure v-for="module in preview.project.modules.slice(0, 3)" :key="module.id"><CanvasPreview :project="preview.project" :module="module" large /><figcaption><span>{{ String(module.index).padStart(2, '0') }}</span>{{ modulePurpose(module).split(' · ')[0] }}</figcaption></figure></div><footer class="preview-footer"><p>{{ applyNotice }}</p><button class="use-button" :disabled="busy" @click="useTemplate(preview.template.id)">{{ useLabel }} <ArrowRight :size="16" /></button></footer></template></dialog>
  </div>
</template>

<style scoped>
