ange);color:white;flex:1}.use-button:hover:enabled{background:#d96043;border-color:#d96043}.apply-note{display:flex;align-items:center;gap:12px;background:#f2f1e9;border:1px solid #e9e7dc;border-radius:9px;padding:18px 20px;margin-top:23px}.note-icon{background:#e9eadd;color:#87906d;padding:9px;border-radius:50%;display:flex}.apply-note strong{font-size:11px;font-weight:600;color:#707b5b}.apply-note p{font-size:10px;line-height:1.8;color:#969e82;margin-top:4px}.preview-dialog{box-sizing:border-box;border:1px solid #e7e5dc;border-radius:16px;background:#fbfaf7;color:#212522;width:min(1060px,calc(100vw - 60px));max-height:90vh;padding:0;box-shadow:0 20px 100px #151b2640;margin:auto}.preview-dialog::backdrop{background:#20262185;backdrop-filter:blur(4px)}.preview-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;padding:25px 28px 22px;border-bottom:1px solid #e8e7e1}.preview-heading h2{font-size:24px;letter-spacing:-.5px;margin:9px 0;font-weight:600}.preview-heading p{font-size:11px;line-height:1.7;color:#93998a}.close-button{border:1px solid #e7e7dd;background:white;border-radius:7px;display:grid;place-items:center;width:33px;height:33px;color:#919886;flex-shrink:0}.close-button:hover{background:#f1f2e9}.preview-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:19px;padding:25px 28px;background:#f1efe8;align-items:start}.preview-gallery figure{margin:0;min-width:0}.preview-gallery :deep(canvas){width:100%;height:auto;box-shadow:0 8px 25px #4c483916;border-radius:3px}.preview-gallery figcaption{display:flex;align-items:center;gap:7px;font-size:11px;color:#7f866e;margin-top:11px}.preview-gallery figcaption span{font-size:9px;color:#9ca388;font-variant-numeric:tabular-nums}.preview-footer{padding:20px 28px;display:flex;align-items:center;justify-content:space-between;gap:25px}.preview-footer p{font-size:10px;color:#9aa18c;line-height:1.7;max-width:650px}.preview-footer .use-button{flex:none;font-size:12px;padding:11px 16px}
.canvas-wrap :deep(.canvas-preview){width:auto;height:100%;max-width:100%}.card-content>p{font-size:12px;color:#858e78;min-height:43px}.style-tags span{font-size:10px}.card-actions button{font-size:11px}.card-heading h2{font-size:16px}.results-heading p{font-size:12px}.results-heading>span{font-size:11px}.apply-note p{font-size:11px}.apply-note strong{font-size:12px}.preview-footer p{font-size:11px}.preview-heading p{font-size:12px}.preview-gallery figcaption{font-size:12px}
